var countEven = function(num) {
    let temp = num, sum = 0;
    while (temp > 0) {
        sum += temp % 10;
        temp = Math.floor(temp / 10);
    }
    return (sum % 2 === 0) ? Math.floor(num / 2) : Math.floor((num - 1) / 2);
};
